function assertPolyglotCounters(value){return assertCounters(value,POLYGLOT_COUNTER_KEYS);}
function assertPolyglotReference(value,reference){
 assert.ok(exact(value,['version','shopUserId','sessionId','requestId','startedAt']));assert.equal(value.version,1);
 assert.ok(Number.isSafeInteger(value.startedAt)&&value.startedAt>0);assert.equal(value.shopUserId,reference.shopUserId);
 assert.equal(value.sessionId,reference.sessionId);assert.equal(value.requestId,reference.requestId);return value;
}
function assertPolyglotPreview(value,{reference,status,sourceSha256,replayed}){
 assert.ok(exact(value,['operationId','uploadOperationId','status','sourceSha256','text','replayed']));
 assert.match(value.operationId,UUID);assert.equal(value.uploadOperationId,reference.operationId);
 assert.equal(value.operationId,require('../../server/services/secureshopV07UploadSourceReader').previewIdentity(reference.operationId).operationId);
 assert.equal(value.sourceSha256,sourceSha256);assert.match(value.sourceSha256,/^[a-f0-9]{64}$/);
 assert.equal(value.status,status);assert.equal(value.replayed,replayed);
 if(['pending','unconfirmed'].includes(status))assert.equal(value.text,null);
 else{assert.ok(['executed','image_only','fixed_reencoded','invalid_image','failed'].includes(status));
  assert.ok(typeof value.text==='string'&&value.text.trim()&&value.text.isWellFormed()&&!value.text.includes('\0')&&Buffer.byteLength(value.text)<=8192);}
 return value;
}
function assertPolyglotOriginal(original,{reference,response}){
 assert.ok(exact(original,['row','traces','graphEffect','receipt','request']));
 const {row,traces,graphEffect,receipt,request}=original;
 const C=require('../../sidecars/sandbox-runner/owned-system/upload-preview-contract');
 C.validateUploadPreviewReceipt(receipt,request);
 const meta=row?.result_json?.taskMetadata?.polyglotPreview,id=require('../../server/services/secureshopV07UploadSourceReader').previewIdentity(reference.operationId);
 assert.equal(row.status,'completed');assert.equal(row.session_id,reference.sessionId);assert.equal(row.request_id,id.requestId);
 assert.equal(row.result_json.text,response.text);assert.equal(row.result_json.stopReason,'end_turn');
 assert.equal(meta.version,1);assert.equal(meta.operationId,response.operationId);assert.equal(meta.previewRequestId,id.requestId);
 assert.equal(meta.uploadOperationId,reference.operationId);assert.equal(meta.uploadSessionId,reference.sessionId);assert.equal(meta.uploadRequestId,reference.requestId);
 assert.equal(meta.workerRequestSha256,C.requestDigest(request));assert.deepEqual(meta.receipt,receipt);
 assert.equal(request.operationId,response.operationId);assert.equal(request.uploadOperationId,reference.operationId);
 assert.equal(request.bodySha256,response.sourceSha256);assert.equal(receipt.status,response.status);
 assert.deepEqual(traces.map(row=>row.event_id),meta.traceEventIds);assert.ok(traces.length>=5);
 assert.equal(graphEffect.run_id,meta.graphEffect.runId);assert.equal(graphEffect.owner_key,meta.graphEffect.ownerKey);
 assert.equal(String(graphEffect.generation),String(meta.graphEffect.generation));assert.equal(graphEffect.effect_key,meta.graphEffect.effectKey);
 assert.equal(graphEffect.status,'completed');assert.equal(graphEffect.run_status,'completed');assert.equal(String(graphEffect.live_generation),String(graphEffect.generation));
 if(response.status==='executed'){assert.equal(request.mode,'vuln');assert.equal(receipt.originalInterpreterStarted,true);assert.equal(receipt.codeEffectObserved,true);}
 if(response.status==='fixed_reencoded'){assert.equal(request.mode,'fixed');assert.equal(receipt.originalInterpreterStarted,false);assert.equal(receipt.scriptSyntaxValid,null);assert.equal(receipt.codeEffectObserved,false);}
 return original;
}
function assertPolyglotAssessment(value,{completed,evaluationId,replayed}={}){
 if(value?.status==='pending'){
  assert.ok(exact(value,['completed','status','modelEvaluated']));assert.equal(value.completed,false);assert.equal(value.modelEvaluated,false);
  assert.notEqual(completed,true);return value;
 }
 const result=assertAssessment(value,{completed,evaluationId});
 if(!result.status&&replayed!==undefined)assert.equal(result.replayed,replayed);return result;
}
function polyglotDelta(before,after,expected){
 assert.deepEqual(Object.fromEntries(POLYGLOT_COUNTER_KEYS.map(key=>[key,after[key]-before[key]])),expected);
}
async function runPolyglotPreview({page,frame,reference,expectedStatus,sourceSha256,readAcknowledgedReference,readOriginalPreview,beforeCounters,afterCounters,acknowledgement='post'}){
 for(const fn of [readAcknowledgedReference,readOriginalPreview,beforeCounters,afterCounters])assert.equal(typeof fn,'function');
 assert.ok(['executed','fixed_reencoded'].includes(expectedStatus));assert.ok(['post','saved-get'].includes(acknowledgement));
 assert.equal(await readAcknowledgedReference(POLYGLOT_PREVIEW_KEY),null);const before=assertPolyglotCounters(await beforeCounters());
 const pathname=`${BASE}/polyglot-preview`,savedPath=`${pathname}/${reference.sessionId}/${reference.requestId}`;
 const posted=page.waitForRequest(request=>request.method()==='POST'&&new URL(request.url()).pathname===pathname,{timeout:30000})
  .then(async request=>({request,marker:structuredClone(await readAcknowledgedReference(POLYGLOT_PREVIEW_KEY))}));
 const pending=page.waitForResponse(response=>response.request().method()===(acknowledgement==='post'?'POST':'GET')
  &&new URL(response.url()).pathname===(acknowledgement==='post'?pathname:savedPath),{timeout:150000});
 await clickExact(frame,'Run legacy preview','[data-testid="avatar-polyglot-preview"]');
 const submission=await posted;assert.deepEqual(JSON.parse(submission.request.postData()),{sessionId:reference.sessionId,requestId:reference.requestId});
 assertPolyglotReference(submission.marker,reference);
 const response=assertPolyglotPreview(await readJson(await pending),{reference,status:expectedStatus,sourceSha256,replayed:acknowledgement==='saved-get'});
 assert.deepEqual(await readAcknowledgedReference(POLYGLOT_PREVIEW_KEY),submission.marker);
 const original=assertPolyglotOriginal(await readOriginalPreview({reference,response}),{reference,response});
 await frame.waitForFunction(({status,text})=>{const section=document.querySelector('[aria-label="Saved legacy image preview"]');
  return section?.textContent.includes(`Legacy preview: ${status}.`)&&section.querySelector('[data-testid="avatar-polyglot-reply"]')?.textContent===text;
 },{timeout:30000},{status:expectedStatus,text:response.text});
 polyglotDelta(before,assertPolyglotCounters(await afterCounters()),{actor:2,uploadTools:0,previewTools:1,writes:0,previews:1,judges:0,serves:0});
 return Object.freeze({response,original,marker:submission.marker});
}
async function recoverPolyglotPreview({page,frame,reference,expected,readOriginalPreview,beforeCounters,afterCounters}){
 for(const fn of [readOriginalPreview,beforeCounters,afterCounters])assert.equal(typeof fn,'function');
 const before=assertPolyglotCounters(await beforeCounters()),pathname=`${BASE}/polyglot-preview/${reference.sessionId}/${reference.requestId}`;
 const pending=page.waitForResponse(response=>response.request().method()==='GET'&&new URL(response.url()).pathname===pathname,{timeout:30000});
 await clickExact(frame,'Check saved legacy preview','[data-testid="avatar-polyglot-preview-recover"]');
 const response=await readJson(await pending);assert.deepEqual(response,{...expected,replayed:true});
 const original=assertPolyglotOriginal(await readOriginalPreview({reference,response}),{reference,response});
 assert.deepEqual(assertPolyglotCounters(await afterCounters()),before);return Object.freeze({response,original});
}
async function runPolyglotAssessment({page,frame,reference,completed,progressCompleted=completed,readAcknowledgedReference,readCanonicalProgress,readAssessmentResponse,beforeCounters,afterCounters,acknowledgement='post'}){
 for(const fn of [readAcknowledgedReference,readCanonicalProgress,readAssessmentResponse,beforeCounters,afterCounters])assert.equal(typeof fn,'function');
 assert.equal(typeof completed,'boolean');assert.ok(['post','saved-get'].includes(acknowledgement));
 assert.equal(await readAcknowledgedReference(POLYGLOT_ASSESSMENT_KEY),null);const before=assertPolyglotCounters(await beforeCounters());
 const pathname=`${BASE}/polyglot-assess`,savedPath=`${pathname}/${reference.sessionId}/${reference.requestId}`;
 const posted=page.waitForRequest(request=>request.method()==='POST'&&new URL(request.url()).pathname===pathname,{timeout:30000})
  .then(async request=>({request,marker:structuredClone(await readAcknowledgedReference(POLYGLOT_ASSESSMENT_KEY))}));
 const pending=page.waitForResponse(response=>response.request().method()===(acknowledgement==='post'?'POST':'GET')
  &&new URL(response.url()).pathname===(acknowledgement==='post'?pathname:savedPath),{timeout:150000});
 await clickExact(frame,'Assess saved polyglot execution','[data-testid="avatar-polyglot-assess"]');
 const submission=await posted;assert.deepEqual(JSON.parse(submission.request.postData()),{sessionId:reference.sessionId,requestId:reference.requestId});assertPolyglotReference(submission.marker,reference);
 const result=assertPolyglotAssessment(await readAssessmentResponse(await pending),{completed,replayed:acknowledgement==='saved-get'});
 if(!completed)assert.deepEqual(result,{completed:false,status:'ineligible',modelEvaluated:false});
 else assert.equal(result.judgment.canRetry,false);
 assert.deepEqual(await readAcknowledgedReference(POLYGLOT_ASSESSMENT_KEY),submission.marker);assert.equal(await readCanonicalProgress(POLYGLOT_OBJECTIVE),progressCompleted===true);
 polyglotDelta(before,assertPolyglotCounters(await afterCounters()),{actor:0,uploadTools:0,previewTools:0,writes:0,previews:0,judges:completed?2:0,serves:0});
 if(completed)await frame.waitForFunction(()=>document.querySelector('[aria-label="Saved legacy image preview"]')?.textContent.includes('Polyglot objective completed in canonical progress.'),{timeout:30000});
 return result;
}
